def apply_upgrade(repo_root: str) -> None:
    assets_dir = os.path.join(repo_root, "Assets")
    if not os.path.isdir(assets_dir):
        print(f"[提示] 当前目录 ({repo_root}) 下未检测到 Assets/ 文件夹，将自动创建目录结构以便预览或拷贝。")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = os.path.join(repo_root, ".backup_v1", stamp)

    updated_count = 0
    created_count = 0

    for rel_path, content in FILES.items():
        full_path = os.path.join(repo_root, *rel_path.split("/"))
        os.makedirs(os.path.dirname(full_path), exist_ok=True)

        if os.path.exists(full_path):
            backup_path = os.path.join(backup_root, *rel_path.split("/"))
            os.makedirs(os.path.dirname(backup_path), exist_ok=True)
            shutil.copy2(full_path, backup_path)
            updated_count += 1
            action = "升级覆盖"
        else:
            created_count += 1
            action = "新增模块"

        with open(full_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(content.lstrip("\n"))

        print(f"  [{action}] {rel_path}")

    print("=" * 76)
    print(f"升级完成！共升级覆盖 {updated_count} 个核心脚本，新增 {created_count} 个 V2 玩法脚本。")
    if updated_count > 0:
        print(f"原版本备份已安全保存至: {backup_root}")
    print("=" * 76)


if __name__ == "__main__":
    target_dir = sys.argv[1] if len(sys.argv) > 1 else os.getcwd()
    apply_upgrade(os.path.abspath(target_dir))